/** The side of a view that carries the current-place edge (spec/01 §1.3). */
enum class SbEdge { Top, Bottom, Start }

/**
 * Draws the 3 dp current-place edge in [color] (pass SebaroTheme.colors.accent and
 * SebaroTheme.tokens.borderWidth.strong) along one side when [show] is true. Pair it with a second cue that is not
 * colour: a filled or check icon, or the title weight.
 */
fun Modifier.sbCurrentEdge(show: Boolean, edge: SbEdge, color: Color, width: Dp): Modifier =
    if (!show) this else drawBehind {
        val w = width.toPx()
        when (edge) {
            SbEdge.Top -> drawRect(color, Offset.Zero, Size(size.width, w))
            SbEdge.Bottom -> drawRect(color, Offset(0f, size.height - w), Size(size.width, w))
            SbEdge.Start -> {
                val x = if (layoutDirection == LayoutDirection.Rtl) size.width - w else 0f
                drawRect(color, Offset(x, 0f), Size(w, size.height))
            }
        }
    }
